mapper.select:
SELECT r.record_id, r.file_id, r.seal_id, r.user_id, r.project_id, r.sign_mode, r.positions, r.has_timestamp, r.span_config, r.client_ip, r.ip_location, r.os_version, r.browser_version, r.status, r.signed_file_id, r.cert_id, r.serial_no, r.fingerprint_sha256, r.verify_status, r.sign_hash, r.page_fingerprint, r.sign_time, r.create_time, r.tenant_id, r.create_user, r.dept_id, p.project_name, s.seal_name, u.nickname AS nick_name, sf.file_name, ss.file_name AS signed_file_name FROM sign_record r LEFT JOIN sign_project p ON r.project_id = p.project_id LEFT JOIN sign_seal s ON r.seal_id = s.seal_id LEFT JOIN sys_user u ON r.user_id = u.id LEFT JOIN sign_file sf ON r.file_id = sf.file_id LEFT JOIN sign_file ss ON r.signed_file_id = ss.file_id
AND r.record_id = #{recordId} AND r.project_id = #{projectId} AND r.seal_id = #{sealId} AND r.user_id = #{userId} AND r.sign_mode = #{signMode} AND r.status = #{status}
ORDER BY r.sign_time DESC

mapper.update:
UPDATE sign_record
status = #{status}, signed_file_id = #{signedFileId}, cert_id = #{certId}, serial_no = #{serialNo}, fingerprint_sha256 = #{fingerprintSha256}, verify_status = #{verifyStatus}, sign_hash = #{signHash}, page_fingerprint = #{pageFingerprint},
WHERE record_id = #{recordId}

